import dotenv from 'dotenv';
import path from 'path';
dotenv.config({ path: path.resolve(__dirname, '../../.env') });

import mongoose from 'mongoose';
import app from './app';

const PORT = process.env.PORT || 5000;
const MONGO_URI = process.env.MONGO_URI || 'mongodb://localhost:27017/nova';

mongoose.connect(MONGO_URI)
  .then(async () => {
    console.log('Connected to MongoDB');

    // Start Gmail webhook watches for notifications
    try {
      const { gmailWebhookService } = await import('./common/services/gmail-webhook.service');
      await gmailWebhookService.startWatchingAllUsers();
      console.log('Gmail webhook service initialized');
    } catch (e) {
      console.error('Gmail webhook failed:', e);
    }

    app.listen(PORT, () => console.log(`Server running on port ${PORT}`));
  });

import express from 'express';
import cors from 'cors';
import helmet from 'helmet';
import cookieParser from 'cookie-parser';
import authRoutes from './modules/auth/routes';
import proposalRoutes from './modules/proposal/routes';

const app = express();

app.use(cors());
app.use(helmet());
app.use(express.json());
app.use(cookieParser());

app.use('/api/auth', authRoutes);
app.use('/api/proposals', proposalRoutes);

export default app;
